query IntegrationStaging($where: IntegrationStagingWhereInput) {
  integrationStaging(
    where: $where
  ) {
    edges {
      node {
        id
        integrationConfigId
        integrationConfig{
          id
          integrationTypeId
          integrationType{
            concurrencyLimit
        }
        }
        statusId
      }
    }
  }
  inprocessRecords: integrationStaging (where: {statusId:  {_eq: "Inprocess"}}){
    edges{
      node{
        integrationConfigId
        integrationConfig{
          integrationTypeId
        }
        _aggregate{
          id{
            count
          }
        }
      }
    }
  }
}

data.transform:
(
  $data := integrationStaging.edges[$isNotNilOrEmpty(node.integrationConfig.id)].node;
  $grouped := $groupBy([$data], function ($v) { $v.integrationConfig.integrationTypeId }).$values($);
  $inprocessRec := $groupBy([$.inprocessRecords.edges.node], function ($v) { $v.integrationConfig.integrationTypeId });
  /* filtering record by concurrency limit and records inprogress */
  $filtered := $grouped.(
    $limit := $first($.integrationConfig.integrationType.concurrencyLimit);
    $intType := $first($.integrationConfig.integrationTypeId);
    $inProcessRecords := ($lookup($inprocessRec, $intType));
    $inProcessCount := $coalesce([$sum($inProcessRecords._aggregate.id.count),0]);
    $data := $;
    $isNotNilOrEmpty($limit) ? ($limit = 0 ? $data : (
      $diff := $limit-$inProcessCount;
      $diff = 0 ? [] : $data#$i[$i < $diff]
    )) : $data;

  );
  [$filtered.$omit($,"integrationConfig")];
)

